// W643 (H-05 & H-16): Parser-level & end-to-end execution verification for every CLI command
// generated by the Console wizards against the real compiled `rustiron`, `rustiron-plan`, and
// `packaging/wordpress-to-emdash.py` tools.
import { describe, expect, it } from "bun:test";
import { existsSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

import {
  buildAppDeployCmd,
  buildAppProvisionCmd,
  buildConfigActivateCmd,
  buildDnsChangeCmd,
  buildDnsZoneImportCmd,
  buildMigrateDryRunCmd,
  buildProductBackupCaptureCmd,
  buildProductRestoreProbeCmd,
  buildProductStandingCaptureCmd,
  buildSiteCredentialRotateCmd,
  buildSiteEjectCmd,
  buildSiteProvisionCmd,
  buildWordPressToEmdashPlanCmd,
  renderCanonicalZone,
  renderDnsOperationsJson,
} from "./cli-commands";

const REPO_ROOT = resolve(import.meta.dir, "../..");
const RUSTIRON_BIN = join(REPO_ROOT, "target/debug/rustiron");
const RUSTIRON_PLAN_BIN = join(REPO_ROOT, "target/debug/rustiron-plan");
const SHA_A = "a".repeat(64);
const SHA_B = "b".repeat(64);
const SNAP_ID = "0".repeat(64);

const PLACEHOLDER_VALUES: Record<string, string> = {
  "<plan_id>": "plan_w643test01",
  "<host_id>": "host_lab_01",
  "<epoch>": "epoch_1",
  "<sha256>": SHA_A,
  "<requester>": "operator",
  "<unix>": "1760000000",
  "<gen>": "gen_0001",
  "<dest_id>": "dest_primary",
  "<snapshot_id>": SNAP_ID,
  "<count>": "12",
  "<bytes>": "4096",
  "<capture_op_id>": "op_cap0001",
};

const FLAG_OVERRIDES: Record<string, string> = {
  "--observed-at": "1759999900",
  "--valid-from": "1760000000",
  "--expires-at": "1760003600",
  "--compensation-until": "1760003700",
  "--first-window-start": "1760000600",
  "--manifest-sha256": SHA_B,
};

function tokenize(command: string): string[] {
  const line = command
    .split("\n")
    .map((l) => l.trim())
    .find((l) => l.length > 0 && !l.startsWith("#"));
  if (!line) throw new Error(`no executable command in: ${command}`);
  const clean = line.replace(/\s*>\s*\S+$/, "");
  const matches = clean.match(/'[^']*'|\S+/g) ?? [];
  return matches.map((tok) => (tok.startsWith("'") && tok.endsWith("'") ? tok.slice(1, -1) : tok));
}

function resolveArg(
  tok: string,
  prev: string | undefined,
  overrides: Record<string, string>,
): string {
  const byFlag = prev ? overrides[prev] : undefined;
  if (byFlag && (tok.startsWith("<") || prev === "--zone-file" || prev === "--operations-file")) {
    return byFlag;
  }
  return PLACEHOLDER_VALUES[tok] ?? tok;
}

function ensureCliBinaries() {
  if (existsSync(RUSTIRON_BIN) && existsSync(RUSTIRON_PLAN_BIN)) return;
  const build = Bun.spawnSync(["cargo", "build", "-q", "-p", "rustiron-cli", "--bins"], {
    cwd: REPO_ROOT,
    stdout: "pipe",
    stderr: "pipe",
  });
  if (build.exitCode !== 0) {
    throw new Error(`cargo build failed: ${build.stderr.toString()}`);
  }
}

function verifyPlanCommand(
  label: string,
  cmd: string,
  work: string,
  files: { zoneFile: string; opsFile: string },
) {
  expect(cmd).not.toContain("--out ");
  expect(cmd).not.toContain("--issuer ");
  expect(cmd).not.toContain("--signer-policy-epoch ");
  const overrides: Record<string, string> = {
    ...FLAG_OVERRIDES,
    "--zone-file": files.zoneFile,
    "--operations-file": files.opsFile,
    ...(label === "product-standing-capture" ? { "--expires-at": "1760260000" } : {}),
  };
  const rawTokens = tokenize(cmd);
  const tokens = rawTokens.map((tok, idx) => resolveArg(tok, rawTokens[idx - 1], overrides));
  expect(tokens[0]).toBe("rustiron");
  const proc = Bun.spawnSync([RUSTIRON_BIN, ...tokens.slice(1)], {
    cwd: REPO_ROOT,
    stdout: "pipe",
    stderr: "pipe",
  });
  if (proc.exitCode !== 0) {
    throw new Error(
      `${label} failed (exit ${proc.exitCode}): ${proc.stderr.toString() || proc.stdout.toString()}`,
    );
  }
  const planPath = join(work, `${label}.plan.json`);
  writeFileSync(planPath, proc.stdout);
  const review = Bun.spawnSync([RUSTIRON_BIN, "plan", "review-file", planPath], {
    cwd: REPO_ROOT,
    stdout: "pipe",
    stderr: "pipe",
  });
  if (review.exitCode !== 0) {
    throw new Error(`rustiron plan review-file failed for ${label}: ${review.stderr.toString()}`);
  }
  if (label !== "product-standing-capture") {
    const inspect = Bun.spawnSync([RUSTIRON_PLAN_BIN, "inspect", planPath], {
      cwd: REPO_ROOT,
      stdout: "pipe",
      stderr: "pipe",
    });
    if (inspect.exitCode !== 0) {
      throw new Error(`rustiron-plan inspect failed for ${label}: ${inspect.stderr.toString()}`);
    }
    expect(inspect.stdout.toString()).toContain("plan digest:");
  }
}

describe("Console CLI command builders match real CLI parsers (W643 / H-05 & H-16)", () => {
  it("generates valid canonical plans accepted by rustiron plan create and rustiron-plan inspect", () => {
    ensureCliBinaries();
    const work = mkdtempSync(join(tmpdir(), "ri-cli-cmd-"));
    try {
      const zoneFile = join(work, "example.com.zone");
      writeFileSync(
        zoneFile,
        renderCanonicalZone({
          zone: "example.com",
          primaryNs: "ns1.example.com",
          secondaryNs: "ns2.example.com",
          ipv4: "203.0.113.10",
          ipv6: "2001:db8::10",
          includeWww: true,
          mailHost: "mx.provider.example",
        }),
      );
      const opsFile = join(work, "ops.json");
      writeFileSync(
        opsFile,
        renderDnsOperationsJson("example.com", [
          { action: "upsert", name: "www", type: "A", ttl: 300, value: "203.0.113.10" },
        ]),
      );

      const commands: [string, string][] = [
        [
          "site-provision",
          buildSiteProvisionCmd({
            siteId: "blogw643",
            hostname: "blog.example.test",
            quotaMib: "2048",
          }),
        ],
        [
          "app-provision",
          buildAppProvisionCmd({
            siteId: "appw643",
            hostname: "app.example.test",
            runtime: "node_22_v1",
            port: 3401,
            healthPath: "/_emdash/api/health",
          }),
        ],
        [
          "app-deploy",
          buildAppDeployCmd({
            siteId: "appw643",
            releaseId: "rel_01",
            runtime: "node_22_v1",
            migrating: true,
          }),
        ],
        ["config-activate", buildConfigActivateCmd({ siteId: "blogw643", note: "test" })],
        ["site-eject", buildSiteEjectCmd({ siteId: "blogw643" })],
        [
          "product-backup-capture",
          buildProductBackupCaptureCmd({ siteId: "blogw643", consistency: "frozen" }),
        ],
        [
          "product-restore-probe",
          buildProductRestoreProbeCmd({ siteId: "blogw643", snapshotId: SNAP_ID }),
        ],
        [
          "product-standing-capture",
          buildProductStandingCaptureCmd({
            siteIds: ["blogw643", "shopw643"],
            periodSeconds: 86_400,
            windowSeconds: 3600,
            maxRuns: 2,
          }),
        ],
        [
          "dns-zone-import",
          buildDnsZoneImportCmd({ zone: "example.com", zoneFile: "./example.com.zone" }),
        ],
        ["dns-change", buildDnsChangeCmd({ zone: "example.com", operationsFile: "./ops.json" })],
        [
          "site-credential-rotate",
          buildSiteCredentialRotateCmd({ siteId: "blogw643", hostname: "blog.example.test" }),
        ],
      ];

      for (const [label, cmd] of commands) {
        verifyPlanCommand(label, cmd, work, { zoneFile, opsFile });
      }
    } finally {
      rmSync(work, { recursive: true, force: true });
    }
  });

  it("emits valid migrate and wordpress-to-emdash.py plan syntax", () => {
    const migrateCmd = buildMigrateDryRunCmd();
    expect(migrateCmd).not.toContain("--source ");
    expect(migrateCmd).toContain("rustiron-plan migrate ./observation.json ./declaration.json");

    const wpCmd = buildWordPressToEmdashPlanCmd({
      wxrPath: "./export.xml",
      mediaDir: "./uploads",
      sourceOrigin: "https://old.example.test",
      targetOrigin: "https://new.example.test",
    });
    const tokens = tokenize(wpCmd);
    expect(tokens.slice(0, 3)).toEqual(["python3", "packaging/wordpress-to-emdash.py", "plan"]);
    const help = Bun.spawnSync(["python3", "packaging/wordpress-to-emdash.py", "plan", "--help"], {
      cwd: REPO_ROOT,
      stdout: "pipe",
      stderr: "pipe",
    });
    expect(help.exitCode).toBe(0);
    const helpOut = help.stdout.toString();
    for (const flag of ["--wxr", "--media-dir", "--source-origin", "--target-origin", "--out"]) {
      expect(tokens).toContain(flag);
      expect(helpOut).toContain(flag);
    }
  });
});
